contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint newMinSum) public {
        uint minSumBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetMinSum(newMinSum); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint minSumAfter = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(
            (!reverted ? minSumAfter == newMinSum : minSumAfter == minSumBefore)
        );
    }
}

